// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
/** Terminal layout: gauges and their colours, cell widths, and packing cells into rows. */

/** A thin bar of `width` cells, in its filled and remaining parts, so each takes its own color. */
export function barParts(percent: number, width = 8): { filled: string; rest: string } {
  const cells = Math.round((Math.min(100, Math.max(0, percent)) / 100) * width)

  return { filled: '━'.repeat(cells), rest: '━'.repeat(width - cells) }
}

/** The bar as one string: what its cells measure. */
export function bar(percent: number, width = 8): string {
  const { filled, rest } = barParts(percent, width)

  return filled + rest
}

export function severityColor(percent: number): string {
  if (percent >= 90) return 'red'
  if (percent >= 70) return 'yellow'

  return 'green'
}

/**
 * Characters a terminal draws over the cell before them: combining marks,
 * Hangul's vowel and final jamo (a decomposed syllable is one wide cell),
 * zero-width spaces and joiners, and variation selectors.
 */
function isZeroWidth(code: number): boolean {
  return (
    (code >= 0x0300 && code <= 0x036f) ||
    (code >= 0x1160 && code <= 0x11ff) ||
    (code >= 0x1ab0 && code <= 0x1aff) ||
    (code >= 0x1dc0 && code <= 0x1dff) ||
    (code >= 0x200b && code <= 0x200f) ||
    (code >= 0x2060 && code <= 0x2064) ||
    (code >= 0x20d0 && code <= 0x20ff) ||
    (code >= 0xd7b0 && code <= 0xd7ff) ||
    (code >= 0xfe00 && code <= 0xfe0f) ||
    (code >= 0xfe20 && code <= 0xfe2f) ||
    code === 0xfeff ||
    (code >= 0xe0100 && code <= 0xe01ef)
  )
}

/** East Asian wide and fullwidth characters, and emoji drawn as pictures: two cells. */
function isWide(code: number): boolean {
  return (
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xa960 && code <= 0xa97f) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe30 && code <= 0xfe4f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x1f300 && code <= 0x1f64f) ||
    (code >= 0x1f680 && code <= 0x1f6ff) ||
    (code >= 0x1f900 && code <= 0x1f9ff) ||
    (code >= 0x1fa70 && code <= 0x1faff) ||
    (code >= 0x20000 && code <= 0x3fffd)
  )
}

/** Terminal cells a string takes: wide characters take two, combining ones none. */
export function displayWidth(text: string): number {
  let width = 0
  for (const char of text) {
    const code = char.codePointAt(0) ?? 0
    width += isZeroWidth(code) ? 0 : isWide(code) ? 2 : 1
  }

  return width
}

/**
 * The escape sequences a program writes for a terminal, each removed whole:
 * CSI (`ESC [`, or its one-byte form) with its parameters and final byte; OSC,
 * DCS, SOS, PM and APC strings up to their terminator; and the short escapes,
 * such as `ESC ( B` from `tput sgr0` and `ESC 7` saving the cursor.
 */
const ESCAPE_SEQUENCE =
  /(?:\u001b\[|\u009b)[0-?]*[ -/]*[@-~]|(?:\u001b[\]PX^_]|[\u0090\u0098\u009d-\u009f])[^\u0007\u001b\u009c]*(?:\u0007|\u001b\\|\u009c)?|\u001b[ -/]*[0-~]/g
/** Every control character but tab and newline: C0, DEL and C1. */
const CONTROL = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g

/**
 * Text from outside the plugin (a file, a prompt, a model's answer, a
 * program's output) as it may be drawn: its escape sequences and control
 * characters removed, tab and newline kept. The engine refuses a whole tree
 * whose text, label, input value or code holds one, and draws the pane blank.
 */
export function printable(text: string): string {
  return text.replace(ESCAPE_SEQUENCE, '').replace(CONTROL, '')
}

/**
 * Splits items into rows no wider than `room`, `gap` cells apart, in order;
 * an item wider than `room` gets a row to itself.
 */
export function packRows<T extends { width: number }>(items: T[], room: number, gap: number): T[][] {
  const rows: T[][] = []
  let used = 0
  for (const item of items) {
    const row = rows[rows.length - 1]
    if (row && used + gap + item.width <= room) {
      row.push(item)
      used += gap + item.width
    } else {
      rows.push([item])
      used = item.width
    }
  }

  return rows
}

/**
 * `text` cut to `width` terminal cells, an ellipsis marking the cut. Counts
 * East Asian wide characters as two cells, so a Korean label never overflows
 * the room it was given.
 */
export function truncate(text: string, width: number): string {
  if (displayWidth(text) <= width) return text
  if (width <= 1) return width === 1 ? '…' : ''
  let out = ''
  let used = 0
  for (const char of text) {
    const cells = displayWidth(char)
    if (used + cells > width - 1) break
    out += char
    used += cells
  }

  return `${out}…`
}

/** `text` padded with spaces to `width` terminal cells, on the start or the end side. */
export function padCells(text: string, width: number, side: 'start' | 'end' = 'end'): string {
  const fill = ' '.repeat(Math.max(0, width - displayWidth(text)))

  return side === 'start' ? fill + text : text + fill
}

files.hooks/shared/time.ts:
// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
import { WEEKDAYS } from './locale'
import type { Locale } from './locale'

/** `2h 56m`, `5d 04h`, `12m`: the second unit always in two digits; `zeroLabel` under a minute. */
export function formatDuration(ms: number, zeroLabel = '0m'): string {
  const minutes = Math.floor(ms / 60000)
  if (Number.isNaN(minutes)) return ''
  if (minutes <= 0) return zeroLabel
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  if (days > 0) return `${days}d ${String(hours).padStart(2, '0')}h`
  if (hours > 0) return `${hours}h ${String(minutes % 60).padStart(2, '0')}m`

  return `${minutes}m`
}

/** `2h 56m`, `5d 16h`, `12m`; `nowLabel` once the reset has passed. */
export function untilReset(resetsAt: string | undefined, now: number, nowLabel = 'now'): string {
  if (!resetsAt) return ''
  const at = Date.parse(resetsAt)
  if (Number.isNaN(at)) return ''

  return formatDuration(at - now, nowLabel)
}

/**
 * The local wall-clock time a window resets at: `17:00` today, otherwise
 * `Wed 10/7 11:00`, or in Korean the date, then the weekday in parentheses. `offsetMinutes` is what
 * `Date#getTimezoneOffset` answers for that instant (UTC minus local).
 */
export function resetClock(
  resetsAt: string | undefined,
  now: number,
  locale: Locale = 'en',
  offsetMinutes?: number,
): string {
  if (!resetsAt) return ''
  const at = Date.parse(resetsAt)
  if (Number.isNaN(at)) return ''
  const offset = (offsetMinutes ?? new Date(at).getTimezoneOffset()) * 60000
  const local = new Date(at - offset)
  const today = new Date(now - offset)
  const time = `${String(local.getUTCHours()).padStart(2, '0')}:${String(local.getUTCMinutes()).padStart(2, '0')}`
  const isToday =
    local.getUTCFullYear() === today.getUTCFullYear() &&
    local.getUTCMonth() === today.getUTCMonth() &&
    local.getUTCDate() === today.getUTCDate()
  if (isToday) return time
  const date = `${local.getUTCMonth() + 1}/${local.getUTCDate()}`
  const weekday = WEEKDAYS[locale][local.getUTCDay()]

  return locale === 'ko' ? `${date}(${weekday}) ${time}` : `${weekday} ${date} ${time}`
}

/**
 * Which day of the last three before a reset it is, counted in local calendar
 * days: 1 on the day of the reset, 2 the day before, 3 the day before that;
 * undefined further off, once it has passed, or with no reset.
 */
export function resetCountdown(resetsAt: string | undefined, now: number, offsetMinutes?: number): 1 | 2 | 3 | undefined {
  if (!resetsAt) return undefined
  const at = Date.parse(resetsAt)
  if (Number.isNaN(at) || at <= now) return undefined
  const offset = (offsetMinutes ?? new Date(at).getTimezoneOffset()) * 60000
  const day = (ms: number) => Math.floor((ms - offset) / 86_400_000)
  const left = day(at) - day(now) + 1

  return left === 1 || left === 2 || left === 3 ? left : undefined
}

/** `17:00(2h 36m)`, `10/7(수) 11:00(2d 20h)`: when a window resets, and how long until then. */
export function resetText(
  resetsAt: string | undefined,
  now: number,
  locale: Locale = 'en',
  nowLabel = 'now',
  offsetMinutes?: number,
): string {
  const clock = resetClock(resetsAt, now, locale, offsetMinutes)
  if (!clock) return ''

  return `${clock}(${untilReset(resetsAt, now, nowLabel)})`
}

files.types/index.d.ts:
/** The workspace pane's tabs. */
export type Tab = 'agents' | 'checkpoints' | 'notes' | 'diff' | 'memory'

/** A subagent or teammate as the Agents tab lists it. */
export type AgentRow = {
  id: string
  /**
   * What TaskStop is asked to stop it by, the surest first: its id, which no
   * other agent holds, then its name and its teammate address, which TaskStop
   * also takes and two agents may share.
   */
  stopIds: string[]
  label: string
  type: string
  status: 'pending' | 'running' | 'waiting' | 'idle' | 'completed' | 'failed' | 'killed'
  /** `$.clock.now()` milliseconds this session first saw it. */
  firstSeen: number
}

/** A git worktree of the session's repository. */
export type WorktreeRow = {
  path: string
  branch?: string
  isMain: boolean
  isLocked: boolean
  /** Changed or untracked paths in it. */
  changed: number
  /** Commits on its branch that the main branch lacks; undefined when unknown. */
  ahead?: number
  behind?: number
}

/** A snapshot of the working tree, kept as a commit under refs/sc/checkpoints. */
export type CheckpointRow = {
  ref: string
  commit: string
  tree: string
  /** `$.clock.now()` milliseconds it was taken. */
  at: number
  /** The prompt it was taken before, or what took it. */
  label: string
  kind: 'turn' | 'session' | 'manual' | 'restore'
  /** A name the person gave it; shown in place of `label`. */
  name?: string
  /** Kept past the newest 50: never deleted to make room. */
  isPinned?: boolean
  /** Changes since it, against the working tree now; absent until counted. */
  since?: { files: number; added: number; removed: number }
}

export type Note = {
  id: string
  text: string
  isDone: boolean
  at: number
  /** The note's number, `N<seq>` in the prompt it is sent with; absent on a note made before numbering. */
  seq?: number
  /** Claude's answer said it finished this note (`[done N<seq>]`); the person confirms. */
  isSuggestedDone?: boolean
}

export type DiffFile = {
  path: string
  /** The old path of a rename. */
  from?: string
  status: 'added' | 'modified' | 'deleted' | 'renamed'
  /** Null for a binary file. */
  added: number | null
  removed: number | null
}

/** A checkpoint one end of the Diff tab's comparison is taken at. */
export type DiffPoint = { commit: string; label: string; at: number; isSessionStart: boolean }

/** What an agent did last, as the Agents tab shows under it. */
export type AgentActivity = {
  /** The tool it last called with what it called it on (`Bash: npm test`), or its last answer's first line. */
  text: string
  /** Whether `text` is its answer: the turn it ran ended. */
  isAnswer: boolean
  /** `$.clock.now()` milliseconds it happened. */
  at: number
}

/** An agent the engine no longer lists, kept for the session with its last activity and full answer. */
export type FinishedAgent = AgentRow & {
  /** `$.clock.now()` milliseconds the engine stopped listing it. */
  endedAt: number
  /** Its last answer in full, when its turn ended with one. */
  answer?: string
}

/** Where a memory file applies: on every project, or on this one. */
export type MemoryScope = 'global' | 'project'

/**
 * What a memory file is to Claude Code: the organisation's policy, the
 * user's CLAUDE.md or rules, the project's CLAUDE.md, local CLAUDE.md, rules,
 * a parent or subfolder's CLAUDE.md, AGENTS.md, a file another imports, or
 * auto memory (its index and its topic files).
 */
export type MemoryKind =
  | 'managed'
  | 'user'
  | 'userRule'
  | 'project'
  | 'local'
  | 'rule'
  | 'pathRule'
  | 'parent'
  | 'subfolder'
  | 'agents'
  | 'imported'
  | 'autoIndex'
  | 'auto'

/** One line of a memory file's outline: a heading, or an index entry. */
export type MemoryOutline = { line: number; text: string; level: number }

/** A memory file as the Memory tab lists it. */
export type MemoryFile = {
  path: string
  /** The path as the tab shows it: from the project, or from home with `~`. */
  display: string
  scope: MemoryScope
  kind: MemoryKind
  bytes: number
  lines: number
  outline: MemoryOutline[]
  /** An auto-memory topic's description, or the file that imports this one. */
  note?: string
}

/** What the Diff tab shows: the files changed since a checkpoint, and one file's diff. */
export type DiffView = {
  /** The checkpoint compared against. */
  base: DiffPoint
  /** The checkpoint compared up to; absent for the working tree as it is now. */
  target?: DiffPoint
  /** Another worktree whose changes are shown, since it parted from the main branch; absent for this one. */
  worktree?: { path: string; branch: string }
  files: DiffFile[]
  selected?: { path: string; text: string; omitted: number }
  /** `$.clock.now()` milliseconds of the comparison. */
  at: number
}

declare module 'claude-code' {
  interface PluginState {
    /** What this plugin reads of the accounts mod's and the toolbox's state. */
    'sc-accounts': {
      paneOpen: boolean
    }
    'sc-toolbox': {
      paneOpen: boolean
    }
    'sc-workspace': {
      tab: Tab
      agents: AgentRow[]
      worktrees: WorktreeRow[]
      /** Why the repository's worktrees and checkpoints cannot be read, or null. */
      repoError: string | null
      checkpoints: CheckpointRow[]
      notes: Note[]
      diff: DiffView | null
      /** What the pane is busy with, as a short key, or null. */
      busy: string | null
      /** `$.clock.now()` of the last agents check while one is active: redraws their elapsed times. */
      clock: number
      /** What the dialog asks: a confirmation, or one end of the Diff tab's comparison; null with no dialog open. */
      dialog: { kind: 'restore' | 'note' | 'stop' | 'worktree' | 'base' | 'target' | 'file' | 'name' | 'memoryScope' | 'memoryRead' | 'diff'; ref: string } | null
      /** What each agent did last, by agent id. */
      activity: Record<string, AgentActivity>
      /** Each agent's last answer in full, by agent id. */
      answers: Record<string, string>
      /** The memory files Claude Code reads here, global and project; null before they are read. */
      memory: MemoryFile[] | null
      /** What the Memory tab searches for; empty to list the files. */
      memoryQuery: string
      /** Which memory files the tab lists. */
      memoryScope: 'all' | MemoryScope
      /** The path of the memory file whose outline is open, or null. */
      memoryOpen: string | null
      /** The page of the open file's diff the diff dialog shows, from 0. */
      diffPage: number
      /** The page of the memory file the reader shows, from 0. */
      memoryPage: number
      /** Agents the engine no longer lists, newest first. */
      finished: FinishedAgent[]
      /** The finished agent whose answer is shown in full, or null. */
      expandedAgent: string | null
      /** The key of the element holding the keyboard in the pane, or null. */
      focused: string | null
      /** Whether this plugin's pane is open, for the accounts mod to read: with both open, the engine draws tabs. */
      paneOpen: boolean
    }
  }
}
